        return -1;
    }

    /* Extract memory_mb */
    if (extract_value(config_line, "memory_mb", memory_str, sizeof(memory_str)) != 0) {
        return -1;
    }

    if (parse_int_value(memory_str, &hw_config->memory_mb) != 0) {
        return -1;
    }

    /* Validate memory is positive */
    if (hw_config->memory_mb <= 0) {
        return -1;
    }

    /* Extract disk_path */
    if (extract_value(config_line, "disk_path", hw_config->disk_path,
                      sizeof(hw_config->disk_path)) != 0) {
        return -1;
    }

    /* Extract network_adapter */
    if (extract_value(config_line, "network_adapter", hw_config->network_adapter,
                      sizeof(hw_config->network_adapter)) != 0) {
        return -1;
    }

    return 0;
}
